  const parsed = parseArguments(raw);          // 1. a JSON object?
  if (!parsed.value) return reject('parse', …);
  const shape = checkSchema(parsed.value, schema); // 2. shape and types
  if (shape.length) return { ok: false, issues: shape };
  const args: CalendarArgs = { topic: …, kind: … }; // 3. now typed
  const meaning = checkMeaning(args);          // 4. rules code knows
